SELECT CASE WHEN s.risk_reward_ratio < 1 THEN 'RR<1' WHEN s.risk_reward_ratio < 1.5 THEN 'RR1-1.5' ELSE 'RR>=1.5' END AS rr_bucket, p.status, COUNT(*) AS n, SUM(p.realized_pnl < 0) AS losers, ROUND(SUM(p.realized_pnl),6) AS pnl_sum, ROUND(AVG((s.take_profit - s.latest_price)/s.latest_price*100),4) AS avg_tp_pct, ROUND(AVG((s.latest_price - s.stop_loss)/s.latest_price*100),4) AS avg_sl_pct FROM crypto_ai.paper_position p JOIN crypto_ai.trade_signal s ON s.id=p.signal_id WHERE p.status IN ('CLOSED','STOPPED') GROUP BY rr_bucket, p.status ORDER BY rr_bucket, p.status;
SELECT p.id, p.symbol, p.close_reason, p.realized_pnl, COUNT(e.id) AS tp_extensions FROM crypto_ai.paper_position p JOIN crypto_ai.wallet_managed_position m ON m.entry_signal_id=p.signal_id JOIN crypto_ai.position_management_event e ON e.wallet_position_id=m.id AND e.event_type='TAKE_PROFIT_EXTENDED' WHERE p.status IN ('CLOSED','STOPPED') GROUP BY p.id, p.symbol, p.close_reason, p.realized_pnl ORDER BY p.realized_pnl LIMIT 100;